Unit Test Code:
#include "unity.h"
#include "buffer.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_clear_clears_buffer_contents(void) {
    // Setup: create a buffer with nonzero data
    buffer_t *buf = helper_make_buffer_with_data("Hello, World!");
    TEST_ASSERT_NOT_NULL(buf);

    // Save original size for later comparison
    size_t orig_size = buffer_size(buf);

    // Precondition: buffer contains the string
    helper_assert_buffer_data_equals(buf, "Hello, World!");
    helper_assert_buffer_length(buf, 13);
    helper_assert_buffer_size(buf, orig_size);

    // Test: clear the buffer
    buffer_clear(buf);

    // Assertions: buffer data is all zero, but size is unchanged
    // The buffer's data should be all '\0' (at least up to buf->len)
    for (size_t i = 0; i < buffer_size(buf); ++i) {
        TEST_ASSERT_EQUAL(0, (unsigned char)buf->data[i]);
    }
    // Length should now be 0 (since data is all '\0')
    helper_assert_buffer_length(buf, 0);
    // Size should remain unchanged
    helper_assert_buffer_size(buf, orig_size);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_clear_clears_buffer_contents);
    return UNITY_END();
}

